def max_window_sum(xs, w):
    if w > len(xs):
        return None
    total = sum(xs[:w])
    best = total
    for right in range(w, len(xs)):
        total += xs[right] - xs[right - w]
        best = max(best, total)
    return best


def longest_unique(s):
    last = {}
    left = best = 0
    for right, ch in enumerate(s):
        if ch in last:
            left = max(left, last[ch] + 1)
        last[ch] = right
        best = max(best, right - left + 1)
    return best
